/*
 * A046239  Numbers whose cube is palindromic in base 8.
 * https://oeis.org/A046239
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, more
 * Formula:   numbers whose cube is palindromic in base 8
 * Range:     u8 n <= 6, u16 n <= 10, u32 n <= 18, u64 n <= 21, u128 n <= 21,
 *            big any n
 * Helpers:   pow_int, terms_up_to
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by: */
/*  - a(1)=0, a(2)=1, a(3)=3,  */
/*  - for k=1,2,3,… produce 8^k + 1,  */
/*  - if k is even also produce 8^k + 8^(k/2) + 1.  */
#include <stdbool.h>
#include "../utils/pow_int.h"
#include "../utils/terms_up_to.h"

seq_t a(idx_t n)
{
    if (n == 1) return (seq_t)0;
    if (n == 2) return (seq_t)1;
    if (n == 3) return (seq_t)3;

    idx_t m = n - 3;                 /* index within the generation loop */
    idx_t low = 1, high = 2 * m;     /* high is safe upper bound */

    while (low < high) {
        idx_t mid = low + (high - low) / 2;
        if (terms_up_to(mid) >= m)
            high = mid;
        else
            low = mid + 1;
    }

    idx_t k = low;
    idx_t prev = terms_up_to(k - 1);
    idx_t offset = m - prev; /* 1 for the base term, 2 for the extra term */

    seq_t val = pow_int((seq_t)8, k);

    if (offset == 1) {
        val += (seq_t)1;
    } else {
        val += pow_int((seq_t)8, k/2);
        val += (seq_t)1;
    }

    return val;
}
